window.MONSTER_CHUNK_141 = [{"name":"Bedlam","cr":9,"xp":6400,"alignment":"CN","size":"Large","type":"aberration","subtypes":["chaotic"],"init":12,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect law"}],"auras":["chaotic resonance 20 ft."],"ac":26,"ac_touch":18,"ac_flat_footed":17,"ac_mods":"+8 Dex, +8 natural, -1 size, +1 dodge","hp":84,"hd":"13d8+26","hdvalue":13,"fort":8,"ref":12,"will":10,"dr":"10/lawful","immunities":["petrification","polymorph","spells and effects with chaotic or anarchic descriptor"],"sr":20,"sr_mods":"vs. spells with lawful descriptor only","speed":[{"type":"fly","speed":50,"maneuverability":"perfect"}],"melee":"2 slams +11 (2d4+3)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"chaos burst"},{"type":"chaotic resonance"}],"strength":17,"dexterity":26,"constitution":15,"intelligence":15,"wisdom":15,"charisma":12,"baseatk":9,"cmb":13,"cmd":32,"cmd_special":"can't be tripped","feats":[{"feat":"Ability Focus (chaos burst)"},{"feat":"Ability Focus (chaotic resonance)"},{"feat":"Blind-Fight"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Improved Initiative"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Fly","value":30},{"skill":"Knowledge (planes)","value":18},{"skill":"Perception","value":24},{"skill":"Stealth","value":20,"special":"+28 in areas of smoke or fog"},{"skill":"Use Magic Device","value":14}],"languages":["Common","plus two others chosen randomly"],"environments":["any underground"],"organizations":["solitary"],"treasure":"standard","description_visual":"This creature has no set form. Before your eyes it seems to shift from a vaguely humanoid form with yellow eyes and no other discernible facial features to a swirling mass of grayish-black crackling matter. In its latter form, blue-gray energy arcs and dances through its form, making it resemble a thundercloud shot through with lightning. It seems to constantly alter its form, as if it has no control over it.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Chaos Burst","kind":"Su","details":": Once per round as a standard action, a bedlam can release a burst of crackling gray energy in a 20-foot radius around itself. Lawful creatures caught in the area take 5d8 points of damage and are staggered for 1d6 rounds. Non-lawful and non-chaotic creatures take 3d8 points of damage, but are not staggered. A successful DC 18 Will save halves the damage and negates the staggered effect. Chaotic-aligned creatures are immune to this effect. The save DC is Constitution-based."},{"type":"Chaotic Resonance","kind":"Su","details":": A bedlam emanates an aura of pure chaos; an invisible and ever-changing ring of chaotic energy. This aura disrupts spells and magic items (except those of a chaotic nature) used within 20 ft. of the bedlam. Spellcasters in the area must make a successful DC 18 caster level check each time they attempt to cast a spell. If the check fails, the spell fizzles away just as if it had been cast. Any magic item used within this area must make a successful DC 18 Fortitude save or lose its magical properties for that round. A new save must be made each round the item remains within the area. These DCs are Constitution-based. Spells with the chaotic descriptor that are cast within this area function as if they were empowered (as by the Empower Spell feat). Chaotically-aligned weapons chaotic damage while in this aura (e.g., an anarchic weapon deals 3d6 total points of chaotic damage while in this aura). Lawful-aligned weapons are unaffected by this aura and also bypass the bedlam's damage reduction."},{"type":"Detect Law","kind":"Su","details":": A bedlam can continuously detect law as the spell (caster level 10th), though there is no chance of it becoming stunned by overwhelming lawful auras. It can suppress or resume this ability as a free action."}],"description":"A bedlam has no control over its form, but its ever-shifting form doesn't hamper its abilities in combat. It is a semi-amorphous, nearly vaporous creature composed of pure chaos that makes its lair in areas tainted with strong concentration of chaotic energies, such as temples to chaotic gods or areas that were once lawfully-aligned but have been poisoned by the effects of chaos. Bedlams are sometimes employed by chaotic wizards or clerics to guard a particular area. Being intelligent, the bedlam is strikes a deal with said employer so that it benefits from the bargain as well. Such deals never last long as the bedlam is an unstable and erratic creature, given to flights of fancy. A bedlam enjoys chaos and seeks to spread it wherever it goes.\n\nBedlams seek to induce chaos and destroy or weaken law with every move. Since it continuously detects law, it uses this ability to discern whether or not those it encounters are of a lawful nature or not. Nonlawful creatures are generally just subjected to one or two chaotic bursts before the creature moves on. If lawful creatures are present, the bedlam unleashes a chaotic burst and moves to melee, forming two limbs from its chaotic mass which it uses to pound its opponents.","ecology":"","habitat_society":""},{"name":"Blood Wight","cr":9,"xp":6400,"alignment":"N","size":"Large","type":"undead","init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":21,"ac_touch":11,"ac_flat_footed":19,"ac_mods":"+2 Dex, +10 natural, -1 size","hp":90,"hd":"12d8+36","hdvalue":12,"hp_mods":["fast healing 5"],"fort":7,"ref":6,"will":9,"defensive_abilities":["channel resistance +5"],"dr":"10/bludgeoning and magic","immunities":["undead traits"],"resists":[{"type":"fire","value":10}],"speed":[{"type":"land","speed":30}],"melee":"2 claws +14 (1d8+5 plus 1 bleed)","space":"10 ft.","reach":"10 ft.","strength":21,"dexterity":15,"intelligence":13,"wisdom":13,"charisma":16,"baseatk":9,"cmb":15,"cmb_special":"+2 vs. grapple","cmd":27,"feats":[{"feat":"Alertness"},{"feat":"Death's Blessing"},{"feat":"Improved Grapple"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Weapon Focus (claws)"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Climb","value":20},{"skill":"Escape Artist","value":18},{"skill":"Perception","value":20},{"skill":"Sense Motive","value":3},{"skill":"Stealth","value":11},{"skill":"Survival","value":11}],"languages":["Common"],"environments":["any"],"organizations":["solitary","pair"],"treasure":"none","description_visual":"This creature looks like a tattered and desiccated humanoid about 8 ft. covered in fresh blood which seems to ooze and weep from its body. Its clothes hang in rags and are soaked in blood as well. Its hands end in sharpened claws and its eyes display no signs of life.","group":"Wight","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Engulf","kind":"Ex","details":"A blood wight can try to wrap a Medium or smaller creature in its body as a standard action. The blood wight attempts a grapple check that doesn't provoke an attack of opportunity. If it wins the grapple check, it establishes a hold and claws its opponent with a +4 bonus on the attack roll. Attacks that hit an engulfing blood wight deal half their damage to the monster and half to the trapped victim. An engulfed victim must hold its breath as long as it remains trapped or begin to drown. A trapped victim can break free with a successful grapple check. A Large blood wight's body can engulf 1 Medium, 2 Small, 4 Tiny, 16 Diminutive, or 32 Fine or smaller opponents."}],"description":"When a living creature bleeds to death on unholy ground, its corpse sometimes returns to life as a blood wight. Evil priests of Orcus, Jubilex, Lucifer and various other demon princes and devil lords often hold dark rituals where they bleed a living creature to death in order to create a blood wight. Blood wights generally detest living creatures, but if created by a clerical or necromantic ritual, the created blood wight will not harm its creator (unless attacked first). Blood wights are solitary creatures though occasionally more than one of these creatures is encountered (particularly when they have been created by an evil cleric or necromancer).\n\nA blood wight stands 8 to 10 ft. tall and weighs 400 to 550 pounds.\n\nIt appears much as it did in life but its body constantly weeps and oozes blood, even leaving footprints as it moves across the ground. Blood wights that could speak in life retain the knowledge of all languages they knew, but for the most part blood wights don't communicate either with others of their kind or with living creatures (including their creator).\n\nA blood wight enters combat slashing with its claws. Given a chance, it grabs the closest opponent and engulfs it, holding it inside its body until it drowns. Drowned foes are ejected from the blood wight's body into a heap on the ground (the blood wight later devours any creature it kills).\n\nA blood wight's natural weapons are treated as magic weapons for the purpose of overcoming damage reduction.","ecology":"","habitat_society":""},{"name":"Bloodsoaker Vine","cr":9,"xp":6400,"alignment":"N","size":"Large","type":"plant","subtypes":["extraplanar"],"init":0,"senses":[{"type":"blindsight","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":19,"ac_touch":9,"ac_flat_footed":19,"ac_mods":"+10 natural, -1 size","hp":115,"hd":"11d8+55 (+11)","hdvalue":11,"fort":14,"ref":3,"will":6,"dr":"10/slashing","immunities":["plant traits"],"speed":[{"type":"land","speed":10},{"type":"climb","speed":10}],"melee":"6 tendrils +14 (1d8+6 plus bleed)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"bleed","details":"1d6"},{"type":"rend","details":"2 tendrils, 1d8+9"}],"strength":22,"dexterity":10,"constitution":21,"intelligence":2,"wisdom":12,"charisma":6,"baseatk":8,"cmb":15,"cmd":25,"cmd_special":"can't be tripped","feats":[{"feat":"Great Fortitude"},{"feat":"Iron Will"},{"feat":"Power Attack"},{"feat":"Toughness"},{"feat":"Vital Strike"},{"feat":"Weapon Focus (tendril)"}],"skills":[{"skill":"Climb","value":14},{"skill":"Perception","value":9},{"skill":"Stealth","value":5}],"environments":["temperate forests","temperate marshes"],"organizations":["solitary","colony (2-5)"],"treasure":"incidental","description_visual":"The vines dangling from the treetops are about as thick as a halfling's leg. They sway gently and almost innocently in the breeze, but the wicked barbs along their lengths glisten unwholesomely with a reddish liquid. The smell of decaying flesh is unmistakable.","source":"Tome of Horrors 4 (3pp)","description":"The bloodsoaker vine is a horrid plant that is believed to have its origins in the blood-stained fields of the Plane of Agony. Some unknown botanist-perhaps one of the N'gathau themselves-supposedly spliced an unknown root from that dismal place with the assassin vine to create this monstrosity. Several other theories as to this plant's origin abound, but this one is the most widely accepted.\n\nThe root system of the bloodsoaker vine needs blood to survive in the same manner as other plants need water. The vine provides nourishment for itself and the host tree from which it dangles by shredding unfortunate forest travelers into easily degraded bits. The trees benefit from the meaty compost while the bloodsoaker vine-true to the name-hungrily feeds on the blood of its victim and any that saturates the nearby soil.\n\nA typical bloodsoaker vine is a mass of roots, vines, and tendrils. Coloration ranges from deep greens to various browns, and all colors in between. The bloodsoaker vine eventually changes colors to better match its surroundings the longer it remains in one location.\n\nIronically, the bloodsoaker vine produces an orchid-like flower thought by many to be among the most beautiful in creation. Far above the carnage below, where its tendrils break the forest canopy, delicate pink blossoms spread their petals and nourish birds and insects with sweet-smelling nectar.","ecology":"","habitat_society":""},{"name":"Brine Drake","cr":9,"xp":6400,"alignment":"NE","size":"Large","type":"dragon","subtypes":["aquatic"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":23,"ac_touch":11,"ac_flat_footed":21,"ac_mods":"+2 Dex, +12 natural, -1 size","hp":105,"hd":"10d12+40","hdvalue":10,"fort":11,"ref":11,"will":8,"immunities":["paralysis","sleep"],"speed":[{"type":"land","speed":20},{"type":"swim","speed":60}],"melee":"bite +14 (2d6+5/19-20 plus grab), tail slap +9 (1d8+2)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"constrict","details":"2d6+7"},{"type":"maelstrom"},{"type":"watery breath"}],"strength":21,"dexterity":15,"constitution":18,"intelligence":8,"wisdom":12,"charisma":12,"baseatk":10,"cmb":16,"cmd":28,"cmd_special":"can't be tripped","feats":[{"feat":"Improved Initiative"},{"feat":"Lightning Reflexes"},{"feat":"Power Attack"},{"feat":"Skill Focus (Stealth)"},{"feat":"Swim-By Attack"}],"skills":[{"skill":"Intimidate","value":14},{"skill":"Perception","value":14},{"skill":"Stealth","value":17},{"skill":"Survival","value":14},{"skill":"Swim","value":26}],"languages":["Draconic"],"sq":[{"type":"amphibious"},{"type":"speed surge"}],"environments":["any oceans"],"organizations":["solitary","pair","wing (3-8)"],"treasure":"standard","description_visual":"This creature resembles a giant eel with a draconic head and a mouth full of razor-sharp teeth. The creature's head has small pectoral and caudal fins. A sail-like dorsal fin runs from the base of its skull to the tip of its tail.","group":"Drake","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Maelstrom","kind":"Ex","details":"Once per day, as a standard action, a brine drake can create a whirlpool within 100 ft. The whirlpool is 50 ft. deep and covers a 30-foot radius at its top. Ships and creatures of the brine drake's size or smaller that come into contact with the whirlpool must succeed on a DC 19 check (Swim check for creatures, Profession [sailor] check for ships) or be pulled into the swirling waters and trapped, spinning around the whirlpool and taking 6d6 points of bludgeoning damage initially and 3d6 points of bludgeoning damage for another 1d6 rounds at which point the whirlpool dissipates. A brine dragon is immune to the effects of its own maelstrom. The check DC is Constitution-based."},{"type":"Savage Bite","kind":"Ex","details":"A brine drake applies 1-1/2 times its Strength bonus to damage dealt with its bite attack, and it threatens a critical hit on a 19-20."},{"type":"Speed Surge","kind":"Ex","details":"Three times per day as a swift action, a brine drake may draw on its draconic heritage for a boost of strength and speed to take an additional move action in that round."},{"type":"Watery Breath","kind":"Su","details":"Once per round, as a standard action, a brine drake can unleash a blast of salt water in a 60-foot cone. Creatures caught in the area take 7d6 points of bludgeoning damage (DC 19 Reflex half). Once a brine drake has used its watery breath, it cannot use it again for 1d6 rounds. The save DC is Constitution-based."}],"description":"Brine drakes are often confused with sea dragons and have a similar appearance to their much larger, and deadlier cousins. Like true sea dragons, brine drakes are the bane of major shipping lanes, lying in shallow water near the surface and attacking small lightly armed vessels and hunting lesser creatures.\n\nBrine drakes make their homes in underwater caverns and the hulls of sunken vessels large enough to handle their huge size. What treasures they scour from the depths of the sea are piled within their caverns.\n\nBrine drakes thankfully mate only once every few years, with a female producing a clutch of two to six eggs. Eggs hatch within 8 months and young reach maturity in roughly 5 years. Brine drakes are over 12 ft. long and weigh around 1,600 pounds. They live up to 300 years.\n\nBrine drakes attack from beneath whenever possible, rising from the waters at great speed, latching their jaws around their target and coiling themselves around other prey or crushing the hulls of vessels under 30 ft. in length. Brine drakes drive other creatures away with slaps of its deadly tail.","ecology":"","habitat_society":""},{"name":"Cave Giant","cr":9,"xp":6400,"alignment":"CE","size":"Huge","type":"humanoid","subtypes":["giant"],"init":1,"senses":[{"type":"low-light vision"}],"ac":19,"ac_touch":9,"ac_flat_footed":18,"ac_mods":"+1 Dex, +10 natural, -2 size","hp":126,"hd":"12d8+72","hdvalue":12,"fort":14,"ref":5,"will":6,"defensive_abilities":["rock catching"],"speed":[{"type":"land","speed":30}],"melee":"Gargantuan greatclub +16 (3d6+12) or 2 slams +15 (2d6+8 plus grab)","ranged":"rock +9 (2d6+12)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"rock throwing","details":"100 ft."},{"type":"pound"},{"type":"trample","details":"2d6+12, DC 20"}],"strength":26,"dexterity":12,"constitution":23,"intelligence":5,"wisdom":11,"charisma":10,"baseatk":9,"cmb":19,"cmb_special":"+4 vs. grapple","cmd":30,"feats":[{"feat":"Diehard"},{"feat":"Endurance"},{"feat":"Iron Will"},{"feat":"Martial Weapon Proficiency (greatclub)"},{"feat":"Power Attack"},{"feat":"Weapon Focus (greatclub)"}],"skills":[{"skill":"Climb","value":15},{"skill":"Perception","value":7},{"skill":"Survival","value":7}],"languages":["Giant"],"sq":[{"type":"oversized weapon use"}],"environments":["any hills","any mountains"],"organizations":["gang (2-5)","clan (6-9 adults plus 35% noncombatants)"],"treasure":"half standard","description_visual":"This massive giant has hideously primitive features and gray blotchy flesh. Unkempt, it wears nothing but filthy rags and carries a tremendous greatclub and its eyes glare maliciously. Most disturbing, its protruding tusk-like teeth hang over its swollen lips causing a steady stream of drool.","group":"Giant","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Pound","kind":"Ex","details":"A cave giant that successfully grabs a foe two or more sizes smaller than itself can smash the opponent into the ground, walls, nearby trees, or other solid objects as a standard action. This deals 2d6+12 points of bludgeoning damage to the victim. In addition, the opponent must make a successful DC 24 Fortitude save or be stunned for one round. A cave giant can perform this action once per round as long as it maintains the grapple. The save DC is Strength-based."},{"type":"Oversized Weapon Use","kind":"Ex","details":"A cave giant wields a Gargantuan greatclub without penalty."}],"description":"Dumber, stronger cousins of hill giants, cave giants live in small communal bands of no more than twelve individuals, with a single male leader that is usually stronger and certainly meaner than all others. They often take up residence in large hill or mountain caves, foraging for food such as mountain goats, bears, and wayward explorers. Extremely primitive and simple-minded, cave giants have no real concept of fire or creature comforts, so they eat their food raw. Cave giants are not rock-throwers like many of their brethren, but they are quite skilled at combat with their huge greatclubs. They take great glee in pounding humans into paste, and then eating the paste.","as_character":[{"description":"","racial_traits":[{"type":"Ability Score Bonuses","value":"+16 Strength, +2 Dexterity, +12 Constitution, -6 Intelligence. Cave giants are dumb, indestructible brutes of primitive intelligence and reasoning and make excellent barbarians."},{"type":"Huge","value":"Cave giants are Huge and take a -2 penalty to AC, -2 penalty to attack rolls, +2 bonus to Combat Maneuver Bonus and Combat Maneuver Defense, and a -8 penalty to Stealth checks. A cave giant's lifting and carrying limits quadruple those of Medium characters. Space 15 ft., Reach 15 ft."},{"type":"Low-light vision","value":"Cave giants can see twice as far as humans in conditions of dim light."},{"type":"Racial Hit Dice","value":"A cave giant begins with twelve levels of giant, which provide 12d8 HD, a base attack bonus of +9, and base save bonuses of Fort +8, Ref +4, Will +4."},{"type":"Racial Skills","value":"A cave giant's humanoid levels give it skill ranks equal to 12 x (2 + Int modifier)."},{"type":"Racial Feats","value":"A cave giant's humanoid levels give it 5 feats."},{"type":"AC","value":"+10 natural armor bonus."},{"type":"Natural Weapons","value":"Cave giants can fight with 2 unarmed strikes that deal lethal damage (2d6+8)."},{"type":"Special Attacks","value":"grab, pound, rock throwing (100 ft.), trample."},{"type":"Special Qualities","value":"Cave giants can use weapons one size greater as described in the over-sized weapon use description above, rock catching."},{"type":"Languages","value":"Cave giants begin play speaking Giant, and can also speak Common if they have an Intelligence of at least 10. Cave giants with high Intelligence scores can choose from the following languages: Gnoll, Goblin, Orc."}]}],"ecology":"","habitat_society":"","gear":"Gargantuan greatclub"},{"name":"Charonodaemon","cr":9,"xp":6400,"alignment":"NE","size":"Medium","type":"outsider","subtypes":["daemon","evil","extraplanar"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"detect magic"},{"type":"see invisibility"}],"ac":24,"ac_touch":13,"ac_flat_footed":21,"ac_mods":"+3 Dex, +11 natural","hp":105,"hd":"10d10+50","hdvalue":10,"fort":12,"ref":12,"will":5,"dr":"10/good","immunities":["acid","death effects","disease","poison"],"resists":[{"type":"cold","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"sr":19,"speed":[{"type":"land","speed":40}],"melee":"quarterstaff +15 (1d6+5)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"fear gaze","details":"30 ft, DC 19 Will save or affected as by fear spell"}],"spell_like_abilities_caster_level":10,"spell_like_abilities_concentration":15,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect magic"},{"spell":"see invisibility"}]},{"frequency":"at-will","spells":[{"spell":"deeper darkness"},{"spell":"desecrate"},{"spell":"greater teleport","details":"self plus skiff only"},{"spell":"plane shift","details":"self plus skiff only"}]},{"frequency":"1/day","spells":[{"spell":"summon","details":"level 4, 1d4 hydrodaemons or 1 charonadaemon 35%"}]}],"strength":21,"dexterity":16,"constitution":21,"intelligence":15,"wisdom":15,"charisma":18,"baseatk":10,"cmb":15,"cmd":28,"feats":[{"feat":"Improved Initiative"},{"feat":"Improved Sunder"},{"feat":"Lightning Reflexes"},{"feat":"Persuasive"},{"feat":"Power Attack"}],"skills":[{"skill":"Bluff","value":17},{"skill":"Diplomacy","value":21},{"skill":"Intimidate","value":21},{"skill":"Knowledge (planes)","value":15},{"skill":"Perception","value":15},{"skill":"Sense Motive","value":15},{"skill":"Stealth","value":16},{"skill":"Survival","value":15}],"languages":["Abyssal","Common","Daemonic","Infernal","telepathy 100 ft."],"sq":[{"type":"alter self"}],"environments":["any Abyss","any (Gehenna)","any (Hades)","any (Nine Hells)","any (Tarterus)"],"organizations":["solitary"],"treasure":"standard coins; 50% goods; 50% items","description_visual":"This creature appears as a skeletal humanoid shrouded in a dark hooded robe. Small pinpoints of crimson light burn in its eye sockets and seem to function as its eyes.","group":"Daemon","source":"Tome of Horrors Complete (3pp)","description":"Charonadaemons resemble their master, Charon, the Boatman of the Lower Planes, and are often mistaken for him. Unlike their master, they care nothing for ferrying souls across the River Styx and seek to murder or steal from those that request passage. Travel across the River Styx by a charonadaemon costs 50 gp per character level per creature seeking passage. The total cost can be in magic items, coins, gems, or any combination of the aforementioned items. Even if the price is paid, the charonadaemon usually betrays his passengers, attempting to dump them into the River Styx or kill them outright. If more money or fare is offered, the charonadaemon can be persuaded not to attack. A charonadaemon can be summoned to the banks of the River Styx by casting blasphemy, holy word, planar ally, planar binding, summon monster IX, or symbol (any). Charonadaemons appear as 6-foot tall skeletal humanoids dressed in black hooded robes.","ecology":"","habitat_society":"","credit":"The Charonadaemon originally appeared in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Chuul-Ttaen","cr":9,"xp":6400,"alignment":"CE","size":"Large","type":"aberration","subtypes":["aquatic"],"init":7,"senses":[{"type":"blindsight","modifier":"60 ft."},{"type":"darkvision","modifier":"60 ft."}],"ac":22,"ac_touch":12,"ac_flat_footed":19,"ac_mods":"+3 Dex, +10 natural, -1 size","hp":138,"hd":"14d8+56","hdvalue":14,"fort":8,"ref":7,"will":11,"defensive_abilities":["darkvision camouflage"],"immunities":["poison"],"weaknesses":["light blindness"],"speed":[{"type":"land","speed":30},{"type":"swim","speed":20}],"melee":"2 claws +17 (2d6+7 plus grab)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"constrict","details":"3d6+7"},{"type":"larvae spray"},{"type":"paralytic tentacles"}],"strength":25,"dexterity":16,"constitution":18,"intelligence":10,"wisdom":14,"charisma":5,"baseatk":10,"cmb":18,"cmb_special":"+4 vs. grapple","cmd":31,"cmd_special":"+4 vs. trip","feats":[{"feat":"Ability Focus (paralysis)"},{"feat":"Alertness"},{"feat":"Blind-Fight"},{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"},{"feat":"Improved Natural Attack (claw)"},{"feat":"Weapon Focus (claw)"}],"skills":[{"skill":"Knowledge (nature)","value":10},{"skill":"Perception","value":23},{"skill":"Sense Motive","value":11},{"skill":"Stealth","value":13},{"skill":"Swim","value":32}],"languages":["Common","Undercommon"],"sq":[{"type":"amphibious"}],"environments":["warm subterranean lakes","warm subterranean rivers"],"organizations":["solitary","pair","pack (3-6)"],"treasure":"standard","description_visual":"A thick armored shell protects this Abyssal-dwelling lobster-like creature. Tiny glowing-red eyes gleam above a mouth full of writhing tentacles.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Darkvision Camouflage","kind":"Ex","details":"A chuul-ttaen is virtually impossible to detect solely using darkvision. A chuul-ttaen is considered invisible (+40 Stealth or +20 Stealth when moving) when encountered in the dark by a creature using darkvision. In lit areas, a chuul-ttaen appears as a ghostly white surface-dwelling chuul."},{"type":"Larvae Spray","kind":"Ex","details":"Once per week as a free action, a female chuul-ttaen can release a spray (15-foot cone) of minute barbed larvae. The initial blast deals 1d8 points of damage and injects larvae into the opponent's body. The affected creature must succeed on a DC 23 Fortitude save to avoid implantation. The save DC is Constitution based. If a chuul-ttaen implants larvae into a paralyzed or otherwise helpless creature, it gets no saving throw. The larvae pupate over the course of 10 days. The host becomes increasing ill suffering a -1 to Strength, Constitution and Dexterity each day of the pupation (-10 maximum) as the pupae absorb nutrients. At the end of the 10 day gestation, 2d4 Diminutive chuul-ttaen burst from the host, killing it in the process. A remove disease or heal spell rids a victim of the larvae/ pupae as does a DC 25 Heal check. If the check fails, the healer can try again, but each attempt (successful or not) deals 1d4 points of damage to the patient. The ability score damage heals normally after the larvae/pupae have been removed."},{"type":"Paralytic Tentacles","kind":"Ex","details":"A chuul-ttaen can transfer a grappled victim from a claw to its tentacles as a move action. The tentacles grapple with the same strength as the claw but deal no damage, instead exuding a paralytic secretion. Anyone held in the tentacles must succeed on a DC 23 Fortitude save each round on the chuul-ttaen‘s turn or be paralyzed for 6 rounds. The save DC is Constitution-based. While held in the tentacles, paralyzed or not, a victim automatically takes1d8+7 points of damage each round from the creature's mandibles."}],"description":"Chuul-ttaens are similar to their normal chuul cousins, possessing many of the same skills, attacks and defenses.\n\nThe ttaen versions are said to swim in the cold depths of the world and only find their way to the surface when summoned by particularly vile wizards. Others claim they are simply underground albino versions of a normal chuul - albeit a more intelligent and deadly monstrosity. The heavily armored chuul-ttaens are excellent swimmers, and often rise up from the depths to grab land-bound creatures in their claws and tentacles.\n\nSome scholars say the ttaen addition to their names is a designation of royalty or a higher ranking in chuul society, although this has not been confirmed.\n\nThe ttaens are able to communicate more easily with other races via a raspy Common speech. Chuul-ttaens have little interest in conversation, however, and are much more likely to attack before asking questions. Only extremely powerful foes give them pause and might warrant words before weapons.\n\nUnderground races fear the chuul-ttaens, claiming the hideous creatures were bred to wipe out all life in the tunnels under the land. They are perfect assassins and even the deadly drow fear these versions that can hide from darkvision.","ecology":"","habitat_society":"","credit":"Original author Gary Schotter & Jeff Harkness  Originally appearing in Splinters of Faith Adventure 8: Pains of Scalded Glass (© Frog God Games/ Gary Schotter & Jeff Harkness, 2011)"},{"name":"Coral Giant","cr":9,"xp":6400,"alignment":"CN","size":"Large","type":"humanoid","subtypes":["giant"],"init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":23,"ac_touch":12,"ac_flat_footed":20,"ac_mods":"+2 Dex, +1 dodge, +11 natural, -1 size","hp":123,"hd":"13d8+65","hdvalue":13,"fort":13,"ref":6,"will":5,"defensive_abilities":["rock catching"],"resists":[{"type":"cold","value":20}],"speed":[{"type":"land","speed":40},{"type":"swim","speed":40}],"melee":"mwk trident +17 (2d6+10) or 2 slams +15 (1d8+7)","ranged":"rock +11 (1d8+10)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"rock throwing","details":"150 ft."},{"type":"water mastery"}],"strength":25,"dexterity":14,"constitution":21,"intelligence":11,"wisdom":12,"charisma":10,"baseatk":9,"cmb":17,"cmd":30,"feats":[{"feat":"Alertness"},{"feat":"Cleave"},{"feat":"Dodge"},{"feat":"Intimidating Prowess"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (trident)"}],"skills":[{"skill":"Craft (jewelry)","value":9},{"skill":"Intimidate","value":14},{"skill":"Perception","value":13},{"skill":"Sense Motive","value":3},{"skill":"Survival","value":10},{"skill":"Swim","value":21}],"languages":["Giant"],"sq":[{"type":"amphibious"},{"type":"water stride"}],"environments":["temperate aquatic","warm aquatic"],"organizations":["solitary","gang (2-5)","hunting party (6-9)","clan (10-20 plus 1 fighter chief of 5th level, and 11-20 sharks)"],"treasure":"standard (masterwork trident)","description_visual":"This towering humanoid has reddish skin and long, dark hair. It is clad in loose-fitting clothes and carries a massive trident.","group":"Giant","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Water Mastery","kind":"Ex","details":"A coral giant gains a +1 bonus on attack and damage rolls if both it and its opponent are touching water. If the opponent or the coral giant is touching the ground, the coral giant takes a -4 penalty on attack and damage rolls. These modifiers apply to bull rush and overrun maneuvers, whether the coral giant is initiating or resisting these kinds of attacks."},{"type":"Water Stride","kind":"Ex","details":"A coral giant suffers no penalties for fighting in or under water (as if affected by a freedom of movement spell)."}],"description":"Coral giants are 12-foot tall humanoids that dwell beneath the waves. They make their homes in great undersea castles constructed of stone. They are generally peaceful creatures and spend their days fishing and tending to their coral farms. Their diet typically consists of undersea plants, fish, and the like, with occasional forays onto land to hunt large game. Trade with other intelligent races is common, with coral giant jewelry being prized by many races. These creatures are on generally good terms with merfolk, tritons, storm giants, and humans. Wars are waged against the sahuagin, krakens, and aboleths, the latter being a particularly hated foe.\n\nCoral giant homes are most always constructed of smooth stone and contain large, open expanses and rooms. Their homes usually contain a few rooms constructed for air-breathers so land-based visitors can move about somewhat freely. Homes are deep under the waters, but no so deep as to be inaccessible to other races looking to trade and bargain. Though coral giants can survive in any waters, they prefer temperate or warm environments to cold temperatures. They can also freely breathe air, but prefer life underwater to land.\n\nCoral giants are, on average, 12 ft. tall and weigh 1,500 pounds. Females tend to be slightly smaller and lighter than males. Skin tones vary in color but are always some shade of coral. Hair color varies from deep blacks to light reds. On very rare occasions, a coral giant is encountered that has white hair. Coral giant's eyes are usually dark blue or green. They can live to be 400 years old. Coral giant leaders are typically fighters or barbarians, though a few are rangers. Druids and clerics are common among coral giants; other spellcasting classes are not.\n\nCoral giants fight with massive tridents in combat, fiercely protecting their territory and young. Creatures not driven off are slaughtered and left for scavenging fish to feed upon.","ecology":"","habitat_society":""},{"name":"Dark Custodian","cr":9,"xp":6400,"alignment":"NE","size":"Medium","type":"undead","subtypes":["incorporeal"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"lifesense","modifier":"60 ft."}],"auras":["unnatural aura (30 ft.)"],"ac":16,"ac_touch":16,"ac_flat_footed":12,"ac_mods":"+2 deflection, +3 Dex, +1 dodge","hp":91,"hd":"14d8+28","hdvalue":14,"fort":6,"ref":7,"will":0,"defensive_abilities":["channel resistance +4","incorporeal"],"immunities":["undead traits"],"weaknesses":["sunlight powerlessness"],"speed":[{"type":"fly","speed":80,"maneuverability":"perfect"}],"melee":"incorporeal touch +13 (1d8 plus energy drain and incorporeal grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"devour"},{"type":"energy drain","details":"1 level, DC 19"},{"type":"silence of the grave"}],"strength":20,"dexterity":16,"intelligence":14,"wisdom":14,"charisma":15,"baseatk":10,"cmb":0,"cmd":14,"feats":[{"feat":"Blind-Fight"},{"feat":"Dodge"},{"feat":"Improved Initiative"},{"feat":"Mobility"},{"feat":"Skill Focus (Perception)"},{"feat":"Spring Attack"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Fly","value":28},{"skill":"Intimidate","value":19},{"skill":"Knowledge (religion)","value":19},{"skill":"Perception","value":25},{"skill":"Spellcraft","value":19},{"skill":"Stealth","value":20}],"languages":["Abyssal","Common","Infernal"],"environments":["any"],"organizations":["solitary","gang (2-4)","swarm (6-11)"],"treasure":"none","description_visual":"A dark robed and hooded figure moves across the floor effortlessly, almost as if floating. Its hands are tucked away in the sleeves of its cassock, and where its face should be is only the blackness of the pit.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Devour","kind":"Su","details":"Any living creature that is pinned by a dark custodian's grapple gains two negative levels per round that the hold is maintained rather than the standard one negative level of its energy drain. Any creature slain by the dark custodian's energy drain is left a steaming, bloody skeleton, all of its soft tissues having been consumed by the undead."},{"type":"Incorporeal Grab","kind":"Su","details":"If a dark custodian hits with an incorporeal touch, it can then attempt to start a grapple as a free action without provoking an attack of opportunity. During the course of this grapple, the dark custodian becomes partially corporeal and its opponent becomes partially incorporeal. This has no game effect other than allowing the dark custodian to use its Strength bonus in its CMB. If it wins the grapple, it establishes a hold at which point its opponent becomes completely incorporeal, as well, along with the dark custodian. The dark custodian automatically begins to devour the held opponent each round he is held. The opponent remains incorporeal until he manages to break the grapple at which time he becomes immediately corporeal. If this occurs within a solid object, the opponent is forcefully ejected from the object's nearest surface, and the opponent takes 1d6 points of damage in the process. The dark custodian must then try to hit with its incorporeal touch attack again to try to reestablish the grapple. Once the dark custodian has an opponent pinned, it attempts to drag him away to devour him in peace."},{"type":"Lifesense","kind":"Su","details":"A dark custodian notices and locates living creatures within 60 ft., just as if it possessed the blindsight ability. It also senses the strength of their life force automatically, as if it had cast deathwatch. Walls less than 5 ft. thick are no impediment to this ability."},{"type":"Silence of the Grave","kind":"Su","details":"As a standard action a dark custodian can use its silence of the grave ability. This creates a silence effect as the spell in a 20-foot radius for 7 rounds. This silent zone acts as a desecrate spell giving the dark custodian a +1 profane bonus on attack rolls, damage rolls and saving throws, as well as, imposing a -3 profane penalty on turn checks. Any living creature within the area of affect must succeed on a DC 19 Will save or become dazed for 1 round. A new save is allowed each round. This is a sonic mind-affecting compulsion effect. Because it takes place in an area of silence, it cannot be counteracted by bardic music. A creature that successfully saves cannot be affected by the daze effect of the same dark custodian's silence of the grave for 24 hours. The save DC is Charisma-based."},{"type":"Sunlight Powerlessness","kind":"Ex","details":"Dark custodians are powerless in natural sunlight (not merely a daylight spell) and flee from it. A dark custodian caught in sunlight cannot attack and can take only a single move action or attack action in a round."},{"type":"Unnatural Aura","kind":"Su","details":"Animals, whether wild or domesticated, can sense the unnatural presence of a dark custodian at a distance of 30 ft. They don't willingly approach nearer than that and panic if forced to do so; they remain panicked as long as they are within that range."}],"description":"Dark custodians are the undead remains of evil clerics tasked to remain behind after death and guard the sacred places of their vile worship. They hate all living things and seek to devour any who come within their guarded precincts. They don't require these feedings for sustenance but rather merely take pleasure in the carnage and brutality.\n\nA dark custodian's true form is hidden beneath its ghostly burnoose with a lightless black void where its face should be. Only in combat are its hands seen, appearing pale with thickened, clawlike nails. They understand the languages they knew in life, but cannot speak.\n\nA dark custodian prefers to attack from ambush, leaping through a solid wall to make an incorporeal grab before dragging its prey back through with it. When attacking in groups they usually surround their prey and use their silence of the grave abilities before trying to grab and drag individual opponents in different directions to be consumed.","ecology":"","habitat_society":"","credit":"Original author Greg A. Vaughan  Originally appearing in Slumbering Tsar (© Frog God Games/ Greg A. Vaughan, 2012)"},{"name":"Dracolisk","cr":9,"xp":6400,"alignment":"N","size":"Large","type":"dragon","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"}],"ac":24,"ac_touch":11,"ac_flat_footed":22,"ac_mods":"+2 Dex, +13 natural, -1 size","hp":115,"hd":"11d12+44","hdvalue":11,"fort":11,"ref":9,"will":17,"immunities":["energy type","sleep","paralysis"],"speed":[{"type":"land","speed":30},{"type":"fly","speed":60,"maneuverability":"poor"}],"melee":"bite +16 (2d6+6), 2 claws +16 (1d6+6)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"breath weapon"},{"type":"petrifying gaze","details":"Fort DC 16"}],"strength":23,"dexterity":14,"constitution":19,"intelligence":6,"wisdom":12,"charisma":13,"baseatk":11,"cmb":38,"cmd":57,"cmd_special":"can't be tripped","feats":[{"feat":"Alertness"},{"feat":"Blind-Fight"},{"feat":"Cleave"},{"feat":"Improved Vital Strike"},{"feat":"Power Attack"},{"feat":"Vital Strike"}],"skills":[{"skill":"Climb","value":14},{"skill":"Diplomacy","value":8},{"skill":"Fly","value":10},{"skill":"Intimidate","value":8},{"skill":"Perception","value":10},{"skill":"Sense Motive","value":10},{"skill":"Stealth","value":5},{"skill":"Survival","value":8},{"skill":"Swim","value":13}],"languages":["Draconic"],"environments":["see text"],"organizations":["solitary","colony (3-6)"],"treasure":"none","description_visual":"This creature resembles a young six-legged dragon with glistening scales and gleaming eyes.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"A dracolisk's breath weapon depends on what type of dragon parent it had, as summarized on the table below. Regardless of its type, a dracolisk's breath weapon is usable once every 1d4 rounds (and no more than three times per day), deals 4d8 points of damage, and allows a DC 19 Reflex save for half damage. The save DC is Constitution-based. Dracolisk Variety Breath Weapon Black 60-foot line of acid Blue 60-foot line of electricity Green 30-foot cone of gas (acid) Red 30-foot cone of fire White 30-foot cone of cold."},{"type":"Immunity to Energy","kind":"Ex","details":"A dracolisk is immune to one type of energy based on its dragon parent and variety. Dracolisk Variety Immunity Black acid Blue electricity Green acid Red fire White cold."},{"type":"Petrifying Gaze","kind":"Su","details":"Turn to stone permanently, range 30 ft., Fortitude DC 16 negates. The save DC is Charisma-based."}],"description":"The vicious dracolisk is a rare crossbreed of dragon and basilisk. No one is quite sure how the dracolisk species came to be, but all who have encountered it are well aware of its lethality. There is believed to be one species of dracolisk for every species of dragon. Thus far, however, most dracolisks encountered have been of the black variety. At first glance, a dracolisk appears to be a juvenile dragon of whatever color its dragon parent was-but thanks to the petrifying gaze it inherited from its basilisk parent, most who encounter a dracolisk never get a second glance. A dracolisk has a scaled body the same color as its dragon parent that fades to a lighter shade on its underside. A short, curved horn, similar to a rhino's, juts from its nose. Its dragon-like wings match its body color but fade to a slightly darker shade near the tips. A dracolisk's eyes are pale green with sparkles that match its dragon-parent color. A typical dracolisk is 15 ft. long and weighs about 3,000 pounds. A dracolisk's environment varies based on its dragon heritage: black dracolisks can be found in warm marshes, deserts, or underground; blue dracolisks favor warm hills and mountains, rarely being found underground; green dracolisks favor temperate or warm forests and underground settings; red dracolisks favor warm mountains and underground settings; and white dracolisks favor cold mountains, cold deserts, and underground. The dracolisk attacks first with its breath weapon and gaze attack. After this, it attacks with its bite and clawed forelegs.","ecology":"","habitat_society":"","credit":"The Dracolisk originally appeared in the First Edition module S4 Lost Caverns of Tsojcanth (© TSR/Wizards of the Coast, 1982) and later in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Draconid","cr":9,"xp":6400,"alignment":"NE","size":"Huge","type":"aberration","init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":23,"ac_touch":10,"ac_flat_footed":21,"ac_mods":"+2 Dex, +13 natural, -2 size","hp":142,"hd":"15d8+60 (+15)","hdvalue":15,"fort":9,"ref":7,"will":9,"dr":"10/magic","resists":[{"type":"fire","value":5}],"speed":[{"type":"land","speed":40},{"type":"climb","speed":20}],"melee":"2 bites +17 (2d6+7 plus poison)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"breath weapon","details":"30-ft. line, 3d6 fire damage, Reflex DC 21 for half, usable every 1d4 rounds per head"},{"type":"web","details":"+13 ranged, DC 23, 15 hp"}],"strength":24,"dexterity":14,"constitution":19,"intelligence":6,"wisdom":14,"charisma":11,"baseatk":11,"cmb":18,"cmd":32,"cmd_special":"+4 vs. trip","feats":[{"feat":"Ability Focus (poison)"},{"feat":"Ability Focus (web)"},{"feat":"Alertness"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Snatch"},{"feat":"Toughness"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Climb","value":20},{"skill":"Perception","value":23},{"skill":"Sense Motive","value":20}],"languages":["Aklo","Undercommon"],"environments":["any underground"],"organizations":["solitary"],"treasure":"standard coins, double goods (gems only), standard items","description_visual":"This hideous creature looks like a cross between a giant spider and dragon or hydra. Where its head should be, two long serpentine necks sprout from its body. Its head and neck are scaled gray, and its spidery torso and eight knobbed legs are covered in short, coarse fur.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 23; frequency 1/round for 6 rounds; effect 1d2 Dex damage; cure 2 consecutive saves."}],"description":"Draconids are a hideous cross between either a giant spider and a hydra or a giant spider and a dragon. They dwell deep underground where they dine on the flesh of elves, dwarves, goblins, and just about anything else that crosses their path. These creatures are never encountered on the surface world, preferring to spend their lives underground.\n\nDraconids are solitary creatures and never mix with others of their own kind (except for mating purposes). If a draconid moves into another's territory, a fight almost always ensues as soon as they discover one another. A typical draconid hunting ground covers an area of nearly 10 miles from its lair.\n\nWhen not hunting, a draconid spends its time in its lair. A draconid's lair is something most disgusting and quite memorable to those that stumble across it. A tangled mess of shiny coins and gems mixed with corpses, bones, and rotted flesh.\n\nA draconid usually waits in its web until prey passes underneath or nearby. It then shoots a web, releases its breath weapon and moves into melee. Once engaged, the draconid bites with one head and breathes fire with the other. One favorite tactic is to slow larger foes with its webs while it snatches up smaller targets in its jaws and crush them, bathing them in fire, and hurling them away if they prove too troublesome.","ecology":"","habitat_society":""},{"name":"Dream Spectre","cr":9,"xp":6400,"alignment":"NE","size":"Medium","type":"outsider","subtypes":["evil","extraplanar","incorporeal"],"init":8,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"dreamsense","modifier":"100 ft."}],"ac":19,"ac_touch":19,"ac_flat_footed":13,"ac_mods":"+4 deflection, +4 Dex, +1 dodge, +0 natural","hp":67,"hd":"9d10+18","hdvalue":9,"fort":5,"ref":10,"will":7,"defensive_abilities":["incorporeal"],"weaknesses":["sunlight powerlessnes"],"speed":[{"type":"fly","speed":60,"maneuverability":"perfect"}],"melee":"incorporeal touch +13 (1d4 plus 1d4 Charisma)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"Charisma damage"},{"type":"heart-stopping fear"},{"type":"nightmare"},{"type":"sleep"}],"dexterity":18,"constitution":15,"intelligence":15,"wisdom":16,"charisma":18,"baseatk":9,"cmb":2,"cmd":13,"feats":[{"feat":"Alertness"},{"feat":"Blind-Fight"},{"feat":"Dodge"},{"feat":"Combat Reflexes"},{"feat":"Improved Initiative"}],"skills":[{"skill":"Bluff","value":15},{"skill":"Diplomacy","value":12},{"skill":"Fly","value":16},{"skill":"Intimidate","value":16},{"skill":"Knowledge (any one)","value":13},{"skill":"Knowledge (planes)","value":10},{"skill":"Perception","value":17},{"skill":"Sense Motive","value":17},{"skill":"Stealth","value":16},{"skill":"Survival","value":15}],"languages":["Common","Dreamspeak"],"environments":["any"],"organizations":["solitary"],"treasure":"none","description_visual":"This creature looks like a vaguely humanoid figure composed of living shadow. White-hot pinpoints of light seem to serve as its eyes. Its arms end in wicked claws of shadowstuff and its lower torso trails off into wispy dark shadows.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Charisma Damage","kind":"Su","details":"Any creature hit by a dream spectre's incorporeal touch attack takes 1d4 points of Charisma damage. At Charisma 0, the victim falls into a nightmare-filled coma until at least 1 point of Charisma is restored."},{"type":"Sunlight Powerlessness","kind":"Ex","details":"A dream spectre caught in sunlight cannot attack and is staggered."},{"type":"Dreamsense","kind":"Su","details":"A dream spectre can automatically pinpoint the presence of dreams within 100 ft. This ability only works against sleeping creatures."},{"type":"Heart-Stopping Fear","kind":"Su","details":"By revealing its true form to a living creature, a dream spectre instills heart-stopping fear in its foe. A creature viewing the dream spectre must succeed on a DC 18 Will save or suffer a heart attack and be reduced to 0 hit points. On the next round the creature drops to -1 hit point and is dying. Whether or not the save is successful, that creature is immune to the heart-stopping fear attack of that dream spectre for one day. This ability only functions against creatures that are awake. The save DC is Charisma-based."},{"type":"Nightmare","kind":"Su","details":"As a full-round action, a dream spectre can touch a sleeping creature and warp and twist its dreams into violent, chaotic nightmares. An affected creature must succeed on a DC 18 Will save or be affected as by a nightmare spell. The save DC is Charisma-based."},{"type":"Sleep","kind":"Su","details":"As a full-round action, a dream spectre can induce sleep in a single creature it touches with its incorporeal touch attack. An affected creature must succeed on a DC 18 Will save or fall asleep for 1 minute. The save DC is Charisma-based."}],"description":"Dream spectres have their origins on a dreamscape plane plagued and flooded with nightmares. This plane is an ever-changing plane of whirling winds, matter, anti-matter, and anything else a dreaming creature injects into the realm of dreams. Dream spectres enter the Material Plane through nexus points created by dreaming creatures, and once on the Material Plane, they use their abilities to attack sleeping and dreaming creatures within their immediate area, feeding on a sleeping creature's dream energy. Once sated, a dream spectre fades into the shadows, only to return the next night. A dream spectre often haunts the same creature night after night until that creature dies or the dream spectre is discovered and flees. Dream spectres look like undead shadows and are often mistaken for them. They are not undead, or even related to undead, so a cleric's power over such creatures doesn't affect a dream spectre. Dream spectres sometimes use this case of mistaken identity to their advantage, seeming to retreat in battle all the while waiting for an opening to strike the unsuspecting cleric. A dream spectre prefers to attack sleeping creatures so it can use its Charisma damaging attack without interruption as well as destroy the target's dreams with its nightmare ability. A creature that awakens or discovers a dream spectre (such as a sentry or guard) is targeted by its sleep attack. Dream spectres attack with their incorporeal touch in combat.","ecology":"","habitat_society":""},{"name":"Elder Acid Quasi-elemental","cr":9,"xp":6400,"alignment":"N","size":"Huge","type":"outsider","subtypes":["acid","elemental","extraplanar"],"init":10,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["fumes (5 ft., Fort DC 20)"],"ac":22,"ac_touch":14,"ac_flat_footed":16,"ac_mods":"+6 Dex, +8 natural, -2 size","hp":114,"hd":"12d10+48","hdvalue":12,"fort":8,"ref":14,"will":10,"dr":"10/-","immunities":["acid","elemental traits"],"weaknesses":["vulnerability to water"],"speed":[{"type":"land","speed":20},{"type":"swim","speed":80}],"melee":"2 slams +17 (1d8+7 plus 1d8 acid)","space":"15 ft.","reach":"15 ft.","special_attacks":[{"type":"acid"},{"type":"drench"}],"strength":25,"dexterity":22,"constitution":19,"intelligence":6,"wisdom":11,"charisma":11,"baseatk":12,"cmb":21,"cmd":37,"feats":[{"feat":"Cleave"},{"feat":"Great Cleave"},{"feat":"Improved Bull Rush"},{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Power Attack"}],"skills":[{"skill":"Knowledge (planes)","value":13},{"skill":"Perception","value":15},{"skill":"Stealth","value":13},{"skill":"Swim","value":30}],"languages":["Aquan"],"environments":["any (Quasi-Plane of Acid)"],"organizations":["solitary"],"treasure":"none","description_visual":"What was once a still puddle of green liquid rises up like a wave, lashing out with acid-dripping tendrils. In the midst of the pool, one can barely make out regions of darker green that form a vaguely human face.","group":"Quasi-elemental","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Acid","kind":"Ex","details":"Acid quasi-elementals are living creatures of acid; any melee hit deals acid damage. Creatures hitting an acid quasi-elemental unarmed or with natural attacks take acid damage as though hit by the quasi-elemental's slam attack."},{"type":"Acid Swimmer","kind":"Ex","details":"Acid quasi-elementals cannot swim in water. The swim speed given in the statistics block is their movement only through acid pools or the acidic nature of their environment on their home plane."},{"type":"Drench","kind":"Ex","details":"The quasi-elemental's touch puts out torches, campfires, exposed lanterns, and other open flames of nonmagical origin if these are of Large size or smaller. The creature can dispel magical fire as dispel magic (caster level equals the quasi-elemental's HD)."},{"type":"Fumes","kind":"Ex","details":"The fumes from an acid quasi-elemental's body act as an inhaled poison. Creatures within 5 ft. of an acid quasi-elemental must make succeed on a Fortitude save or take 1 point of Constitution damage each round. This poison doesn't have a frequency; a creature is safe as soon as it moves more than 5 ft. away from the acid quasi-elemental."},{"type":"Vulnerability to Water","kind":"Ex","details":"An acid elemental erupts in a violent chemical reaction when touched by water. An acid quasi-elemental takes 1d4 points of fire damage for each gallon of water poured into it. The reaction is so violent that all creatures within 5 ft. of the acid quasi-elemental when the water hits it must succeed on a DC 15 Reflex save or take the same damage. Pouring water onto an acid quasi-elemental requires a successful ranged touch attack. Water from other sources, such as spells or effects that create water but don't specify an amount in gallons, deal 1d4 points of fire damage per caster level to an acid quasi-elemental within its area of effect. Damage from water-based attacks, like the slam attack of a water elemental, is increased by 50% against an acid quasi-elemental. Note that this reaction doesn't occur when the acid quasi-elemental touches water, only when water touches the acid quasi-elemental."}],"description":"Nestled among the various elemental there lies a plane composed entirely of acid. It is a place of noxious fumes and roiling, bubbling, pools. Plane jumpers do well to avoid this place as it is considered by many to be one of the deadliest, if not the deadliest, of the elemental-based planes. Acid quasi-elementals rarely journey from their native plane, except when summoned. They don't like the Material Plane and when called to the place, are usually angered and always a bit uncomfortable. They have no trouble moving on land, but prefer the sanctity of their native plane to all others. At rest, an acid quasi-elemental is a clear puddle of liquid with a slightly green hue. It can rise up like a wave in a manner similar to a water elemental, or ooze along solid surfaces by sending out tendrils and pulling itself along. Wherever it travels, it leaves behind a shallow trough that emits wisps of smoke. Acid quasi-elementals are almost always encountered in large pools of acid when on the Material Plane and rarely leave these pools when combating foes. A favored tactic is to grab a foe and pull it into the quasi-elemental's acid pool, subjecting it to massive amounts of acid damage.","ecology":"","habitat_society":""},{"name":"Elder Obsidian Quasi-elemental","cr":9,"xp":6400,"alignment":"N","size":"Huge","type":"outsider","subtypes":["earth","elemental","extraplanar"],"init":-1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":21,"ac_touch":7,"ac_flat_footed":21,"ac_mods":"-1 Dex, +14 natural, -2 size","hp":114,"hd":"12d10+48","hdvalue":12,"fort":8,"ref":7,"will":8,"dr":"10/-","immunities":["elemental traits"],"resists":[{"type":"cold","value":10},{"type":"fire","value":10}],"speed":[{"type":"land","speed":20}],"melee":"2 claws +20 (2d6+10/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"death throes"},{"type":"molten glass","details":"2d8 fire, DC 20"}],"strength":30,"dexterity":8,"constitution":19,"intelligence":6,"wisdom":11,"charisma":11,"baseatk":12,"cmb":24,"cmd":31,"feats":[{"feat":"Awesome Blow"},{"feat":"Cleave"},{"feat":"Great Cleave"},{"feat":"Improved Bull Rush"},{"feat":"Improved Critical (claw)"},{"feat":"Improved Natural Attack","type":"bonus"},{"feat":"Power Attack"}],"skills":[{"skill":"Knowledge (planes)","value":13},{"skill":"Perception","value":15},{"skill":"Sense Motive","value":15},{"skill":"Stealth","value":6}],"languages":["Terran"],"environments":["any (Quasi-Plane of Obsidian)"],"organizations":["solitary"],"treasure":"none","description_visual":"This creature is a powerfully built, roughly humanoid-shaped monolith of black stone. Its hands end in wicked, serrated and jagged claws. No facial features can be discerned.","group":"Quasi-elemental","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Death Throes","kind":"Ex","details":"When reduced to 0 or less hit points, an obsidian quasi-elemental explodes in a cloud of razor-sharp bits of obsidian. A creature caught in the area can make a Reflex save for half damage. The save DC is Constitution-based."},{"type":"Molten Glass","kind":"Ex","details":"A successful hit against an obsidian quasi-elemental with a piercing or slashing weapon (or piercing or slashing natural attack) that deals damage equal to its current HD opens a wound that spurts molten glass. The wound bleeds for 1d4 rounds and any creature within 5 ft. must make a Reflex save or take fire damage from the splash. A new save must be made each round the wound bleeds and a creature is within the area. The save DC is Constitution-based."}],"description":"In a quasi-realm where elemental water and elemental fire conjoin, there exists a pocket plane known as the Quasi-plane of Obsidian; a plane of barren wastes and blackened rock, of razor-sharp obelisks and fields of sharpened glass. Creatures native to this plane appear as blackened obsidian with jagged, serrated, or clear-cut angles and edges. Some have barbed spikes adorning their elemental forms. Obsidian quasi-elementals are usually encountered on their home plane or on the Plane of Fire. Still some can be found on the Obsidian Plain in the Plane of Molten Skies. Most, however, prefer the serenity that the Quasi-plane of Obsidian offers, and thus they rarely venture forth unless summoned. Obsidian quasi-elementals are deadly combatants and strike with their sharpened claws, ripping and tearing at their opponents. They are relentless in their attacks and never give quarter.","ecology":"","habitat_society":""},{"name":"Entropic Ooze","cr":9,"xp":6400,"alignment":"N","size":"Large","type":"ooze","subtypes":["extraplanar"],"init":-2,"senses":[{"type":"blindsight","modifier":"60 ft."},{"type":"soulsight","modifier":"120 ft."}],"ac":12,"ac_touch":7,"ac_flat_footed":12,"ac_mods":"-2 Dex, +5 natural, -1 size","hp":137,"hd":"11d8+88","hdvalue":11,"fort":11,"ref":1,"will":-2,"immunities":["negative energy","ooze traits"],"sr":24,"sr_mods":"vs. positive energy","speed":[{"type":"land","speed":20},{"type":"climb","speed":20}],"melee":"slam +13 (2d6+9 plus energy drain)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"devour soul"},{"type":"energy drain","details":"2 levels, DC 15"}],"strength":23,"dexterity":6,"constitution":26,"wisdom":1,"charisma":10,"baseatk":8,"cmb":15,"cmd":23,"cmd_special":"can't be tripped","skills":[{"skill":"Climb","value":14}],"environments":["any (Plane of Negative Energy)"],"organizations":["solitary"],"treasure":"none","description_visual":"This protoplasmic creature resembles a giant amoeba, black in color. A deathly cold seems to emanate from its form.","group":"Ooze","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Devour Soul","kind":"Su","details":"A living creature slain by an entropic ooze has its soul devoured by the ooze. Such a creature cannot be returned to life until the entropic ooze that contains its soul is slain."},{"type":"Soulsight","kind":"Su","details":"An entropic ooze can automatically detect the location of any living creature within 120 ft. It also senses the strength of their life force automatically, as if it had cast deathwatch."}],"description":"An entropic ooze is a dangerous and deadly protoplasmic creature thought to have arrived on the Material Plane from another dimension or time. Its sole purpose seems to be the collection and destruction of the souls of the living. Some tales spoken only in whispers say the entropic ooze is the creation of an insane god, sent to destroy life so that the gods may remake creation. Others conjecture that the entropic ooze is the creation of some vile and evil spellcaster warped on the perverseness of its own destruction and that of the world around it. Whatever its true purpose, the entropic ooze is a deadly creature that seems to have no useful purpose in the ecosystem, save perhaps to those of a destructive nature.\n\nEntropic oozes can be found just about anywhere, though most are found in or near locations frequented by living creatures. They prefer areas of darkness, such as subterranean caves, dungeons, and the like, where their naturally dark coloration allows them to blend into the natural darkness.\n\nAn entropic ooze is an amorphous and swirling mass of black protoplasm that covers an area of 10 ft. or more. Its form resembles that of a black pudding and it is often mistaken for said creature. The entropic ooze is naturally cold to the touch and those that have contacted the ooze (and lived), speak of the unnatural energy they felt flowing through it.\n\nThe screams of those that have been absorbed are thought to be heard emanating from the creature's form as it undulates along.\n\nA entropic ooze is driven by its hunger and need to absorb souls. It attacks by forming pseudopods from its protoplasmic form or by simply rolling over its opponents and absorbing them into its form. After devouring the soul of an engulfed creature, the entropic ooze ejects the creature's physical body, now a dried and crumbling husk. An entropic ooze prefers to absorb as many creatures as it can into its body, and then pummel those that avoid being engulfed with its powerful pseudopods.","ecology":"","habitat_society":""},{"name":"Geon","cr":9,"xp":6400,"alignment":"N","size":"Large","type":"outsider","subtypes":["earth","elemental","extraplanar"],"init":-1,"senses":[{"type":"darkvison","modifier":"60 ft."}],"ac":22,"ac_touch":8,"ac_flat_footed":22,"ac_mods":"-1 Dex, +14 natural, -1 size","hp":92,"hd":"8d10+48","hdvalue":8,"fort":12,"ref":1,"will":7,"dr":"5/-","immunities":["elemental traits"],"resists":[{"type":"fire","value":5}],"sr":20,"speed":[{"type":"land","speed":20}],"melee":"2 slams +15 (2d8+7)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"animate boulders"}],"spell_like_abilities_caster_level":8,"spell_like_abilities_concentration":14,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"stone shape"}]},{"frequency":"1/day","spells":[{"spell":"move earth"},{"spell":"passwall"},{"spell":"transmute rock to mud"},{"spell":"wall of stone"}]}],"strength":25,"dexterity":9,"constitution":22,"intelligence":10,"wisdom":12,"charisma":13,"baseatk":8,"cmb":16,"cmb_special":"+4 vs. bull rush","cmd":25,"cmd_special":"+4 vs. bull rush","feats":[{"feat":"Greater Bull Rush"},{"feat":"Improved Bull Rush"},{"feat":"Power Attack"},{"feat":"Weapon Focus (slam)"}],"skills":[{"skill":"Appraise","value":11},{"skill":"Knowledge (planes)","value":11},{"skill":"Climb","value":17},{"skill":"Perception","value":12},{"skill":"Stealth","value":8,"special":"+14 in stony environs"},{"skill":"Survival","value":12}],"languages":["Common","Terran"],"sq":[{"type":"freeze"}],"environments":["any (Elemental Plane of Earth)"],"organizations":["solitary","gang (2-5)","colony (5-8)"],"treasure":"standard","description_visual":"An immense boulder-like creature emerges from the earth. It props itself upon two large legs and ft., which also seem to serve as the creatures hands. Two large recesses on its surface function as eyes and its moth stretches wide.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Animate Boulders","kind":"Sp","details":"A geon can animate rocks within 180 ft. at will, controlling up to two rocks at a time. Boulders move at a speed of 10 ft. and fight as a geon in all respects. Animated boulders lose their ability to move if the geon that animated them is incapacitated or moves out of range. The ability is otherwise similar to liveoak (caster level 15th), but affects rocks rather than trees. Animated boulders have the same vulnerability to cold that a geon has."}],"description":"Geons are natives of the Elemental Plane of Earth. They are sometimes summoned by powerful spellcasters to do their bidding, usually acting as protectors or guardians. Some, however, find their way to the Material Plane on their own when a portal between the two planes opens. On the Material Plane, geons are found in mountains, barren hills, and other rocky environments.\n\nMost geons have been given a task by an earth god and live to faithfully carry out that task.\n\nA geon's voice is low and rumbling, sounding like stones grinding together whenever the creature speaks.\n\nGeons shun combat if possible, using their special abilities to hide in the surrounding earth. If the geon has a task and that task is threatened, the guardian doesn't hesitate to enter combat or use its abilities to animate boulders to attack its foes and create walls of stone to contain them.","ecology":"","habitat_society":""},{"name":"Ghirru","cr":9,"xp":6400,"alignment":"LE","size":"Large","type":"undead","subtypes":["extraplanar","fire"],"init":3,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":23,"ac_touch":13,"ac_flat_footed":19,"ac_mods":"+3 Dex, +1 dodge, +10 natural, -1 size","hp":95,"hd":"10d8+50","hdvalue":10,"fort":10,"ref":6,"will":9,"dr":"5/good","immunities":["fire","undead traits"],"weaknesses":["vulnerability to cold"],"speed":[{"type":"land","speed":30}],"melee":"2 claws +15 (1d8+8 plus burn and grab), bite +14 (2d6+8 plus burn)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"burn","details":"1d8, DC 20"}],"strength":27,"dexterity":17,"intelligence":12,"wisdom":14,"charisma":20,"baseatk":7,"cmb":16,"cmb_special":"+4 vs. grapple","cmd":30,"feats":[{"feat":"Cleave"},{"feat":"Dodge"},{"feat":"Great Fortitude"},{"feat":"Power Attack"},{"feat":"Weapon Focus (claws)"}],"skills":[{"skill":"Bluff","value":15},{"skill":"Intimidate","value":18},{"skill":"Perception","value":19},{"skill":"Sense Motive","value":15},{"skill":"Stealth","value":12}],"languages":["Aquan","Auran","Common","Ignan","Terran"],"sq":[{"type":"change shape","details":"flame-spawned dire wolf; doesn't detect as undead in this form; beast shape II"},{"type":"genie-kin"}],"environments":["any (Plane of Fire)"],"organizations":["solitary","pack (2-6)"],"treasure":"standard","description_visual":"This undead creature's flesh is burned and charred and hangs loosely about its form. The stench of burnt flesh permeates the air as it draws closer.","source":"Tome of Horrors 4 (3pp)","special_abilities":[{"type":"Burn","kind":"Ex","details":"A ghirru deals burn damage each round it grapples. A creature that catches on fire cannot extinguish the flames until it first escapes the grapple."},{"type":"Change Shape","kind":"Su","details":"A ghirru can assume the shape of a Large flame-spawned dire wolf. A flame-spawned dire wolf is an 8 HD dire wolf with the following abilities: immunity to fire, vulnerability to cold, deals 1d6 points of fire damage with its bite attack."},{"type":"Genie-kin","kind":"Ex","details":"For all race-related effects (such as a ranger's favored enemy), a ghirru is considered a genie even though its type is undead."}],"description":"Ghirru are undead efreet, returned to the land of the living by efreeti necromancers through foul and dark magic. A ghirru closely resembles its original efreeti form, save its flesh is charred and hangs loosely about it, sometimes falling off in pieces as the creature moves.\n\nGhirru haunt cemeteries, ruins, ancient temples to the efreet gods, and other such places. Legend speaks of a large lair of these creatures led by a sorcerer of vast power hidden somewhere beneath the fabled City of Brass. None have found this secret lair thus far. And few go looking for it.\n\nGhirru have a taste for genie flesh, particularly djinn and marid, though the latter is often hard to come by on the Plane of Fire. When hunting on the Material Plane, ghirru are found in warmer lands, often near extinct volcanoes and other such warm places.\n\nA ghirru stands 12 ft. tall and weighs around 1,500 pounds. Its skin is charred and burned, though in a few places the original crimson color shines through. Its body constantly emanates small wisps of smoke, and the smell of burnt flesh lingers in the air around the creature.\n\nA ghirru attacks with its claws and bite, attempting to grab its prey and set it on fire. A grappled creature is held and incinerated, then promptly devoured by the ghirru.","ecology":"","habitat_society":""},{"name":"Gohl","cr":9,"xp":6400,"alignment":"CE","size":"Large","type":"aberration","init":7,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":22,"ac_touch":12,"ac_flat_footed":19,"ac_mods":"+3 Dex, +10 natural, -1 size","hp":119,"hd":"14d8+56","hdvalue":14,"fort":8,"ref":9,"will":12,"defensive_abilities":["all-around vision"],"dr":"10/silver","speed":[{"type":"fly","speed":30,"maneuverability":"good"}],"melee":"3 bites +15 (1d4+5 plus 1d6 acid), 6 tentacles +12  (1d6+2 plus grab)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"constrict","details":"1d6+5"}],"strength":20,"dexterity":17,"constitution":19,"intelligence":6,"wisdom":12,"charisma":6,"baseatk":10,"cmb":16,"cmb_special":"+4 vs. grapple","cmd":29,"cmd_special":"can't be tripped","feats":[{"feat":"Improved Initiative"},{"feat":"Iron Will"},{"feat":"Lightning Reflexes"},{"feat":"Multiattack"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Fly","value":9},{"skill":"Intimidate","value":10},{"skill":"Knowledge (dungeoneering)","value":5},{"skill":"Perception","value":25}],"languages":["Common (can't speak)"],"environments":["any underground"],"organizations":["solitary"],"treasure":"standard","description_visual":"This creature appears as a floating blob of mottled black and gray flesh.  From its central form sprouts six long tentacles and three snake-like heads, each head perched atop a thin, serpentine neck. Each head has a gaping maw lined with pointed fangs. Many smaller tentacles jut from its central form only to disappear back into its trunk just as quickly as they appeared.","source":"Tome of Horrors Complete (3pp)","description":"Gohls are nightmarish creatures found lurking in desolate ruins or subterranean caverns. No one is quite sure of their true origin and some sages believe they may have traveled to the Material Plane from another dimension or time. They are solitary creatures and favor humanoid prey above all others, though they are not adverse to attacking and devouring any living creature encountered.\n\nA gohl is a 10-foot wide, 10-foot high, blob of mottled black and gray flesh, slimy and rubbery to the touch. Each of its three heads is gold with red eyes and has a wide mouth lined with double rows of needle-sharp teeth. Each neck is scaled gold and turns to dark green as it nears the gohl's body. The underside of each neck is slightly lighter in color.\n\nGohls communicate with others of their kind by changing the color of their trunk. In combat, a gohl can release a loud, metallic-sounding roar from one of its heads and often does so, in an effort to scare its adversaries.\n\nGohl's make no effort to disguise themselves or hide from opponents. As soon as intruders are detected in their area, they move to intercept them.\n\nThe gohl begins combat by grabbing a foe with a tentacle. A grabbed foe is subjected to as many bite attacks each round as the gohl can bring against it. Multiple opponents are often grabbed and bitten as well. Foes that are killed by a gohl are carried to its lair and digested.","ecology":"","habitat_society":""},{"name":"Gorgimera","cr":9,"xp":6400,"alignment":"N","size":"Large","type":"magical beast","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":18,"ac_touch":10,"ac_flat_footed":17,"ac_mods":"+1 Dex, +8 natural, -1 size","hp":95,"hd":"10d10+40","hdvalue":10,"fort":11,"ref":8,"will":4,"speed":[{"type":"land","speed":40},{"type":"fly","speed":50,"maneuverability":"poor"}],"melee":"2 bites +14 (2d6+4), slam +13 (1d6+4), 2 claws +13 (1d6+4)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"breath weapon","details":"varies"}],"strength":19,"dexterity":13,"constitution":19,"intelligence":4,"wisdom":13,"charisma":10,"baseatk":10,"cmb":15,"cmd":26,"feats":[{"feat":"Ability Focus (dragon breath weapon)"},{"feat":"Flyby Attack"},{"feat":"Hover"},{"feat":"Power Attack"},{"feat":"Weapon Focus (bite)"}],"skills":[{"skill":"Fly","value":2},{"skill":"Perception","value":6},{"skill":"Stealth","value":4}],"languages":["Draconic"],"environments":["temperate hills","temperate mountains"],"organizations":["solitary","pair"],"treasure":"standard","description_visual":"This hideous creature has leathery dragon wings and three heads; a lion, a dragon, and a gorgon. Its hindquarters are that of a gorgon and its forequarters are that of a great lion.","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Breath Weapon","kind":"Su","details":"A gorgimera has two breath weapons, each of which can be used independently of the other (thus it can breathe twice in a given round as a single standard action). Dragon A gorgimera's dragon head breath weapon depends on the color of its dragon head, as summarized on the table below. Regardless of its type, a gorgimera's breath weapon is usable once every 1d4 rounds, deals 3d8 points of damage, and allows a DC 21 Reflex save for half damage. The save DC is Constitution-based. To determine a gorgimera's head color and breath weapon randomly, roll 1d10 and consult the table below. 1d10 Head Color Breath Weapon 1-2 Black 40-foot line of acid 3-4 Blue 40-foot line of lightning 5-6 Green 20-foot cone of gas (acid) 7-8 Red 20-foot cone of fire 9-10 White 20-foot cone of cold Gorgon A gorgimera's gorgon head breath weapon is usable once every 1d4 rounds (no more than twice per day), turns a creature to stone permanently, and allows a DC 19 Fortitude save to avoid. The save DC is Constitution-based. The breath weapon is a 30-foot cone."}],"description":"A gorgimera is a chimerical creature with the heads of a lion, dragon, and gorgon. It has the hindquarters of a gorgon and the forequarters of lion. It is a highly territorial predator whose hunting range often covers several square miles around its lair. The creature makes its home inside caves high atop mountains or deep inside caverns. A typical lair contains a mated pair and one or two young. A gorgimera's dragon head can be that of any of the evil dragons. The lion head has no mane, and the scaled gorgon head is a deep navy blue with glowing red eyes. A gorgimera prefers to attack from ambush. It usually attacks by biting with its lion head and dragon head, butting with its gorgon head, and slashing with its front leonine paws. In lieu of biting, the dragon head and gorgon head can emit their respective breath weapons.","ecology":"","habitat_society":"","credit":"The Gorgimera originally appeared in the First Edition module S4 Lost Caverns of Tsojcanth (© TSR/Wizards of the Coast, 1982) and later in the First Edition Monster Manual II (© TSR/Wizards of the Coast, 1983) and is used by permission."},{"name":"Greater Gelid Beetle","cr":9,"xp":6400,"alignment":"N","size":"Large","type":"magical beast","subtypes":["cold"],"init":4,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":22,"ac_touch":9,"ac_flat_footed":22,"ac_mods":"+13 natural, -1 size","hp":114,"hd":"12d10+48","hdvalue":12,"fort":12,"ref":10,"will":4,"immunities":["cold"],"weaknesses":["vulnerability to fire"],"speed":[{"type":"land","speed":30}],"melee":"bite +18 (1d6+9/19-20 plus 1d8 cold)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"cold"},{"type":"cold cloud"}],"strength":23,"dexterity":10,"constitution":18,"intelligence":2,"wisdom":10,"charisma":9,"baseatk":12,"cmb":19,"cmd":29,"feats":[{"feat":"Improved Critical (bite)"},{"feat":"Improved Initiative"},{"feat":"Power Attack"},{"feat":"Skill Focus (Perception)"},{"feat":"Weapon Focus (bite)"},{"feat":"Lightning Reflexes"}],"skills":[{"skill":"Perception","value":12},{"skill":"Stealth","value":5,"special":"+9 natural surroundings"}],"environments":["cold forests"],"organizations":["solitary","cluster (2-5)"],"treasure":"none","description_visual":"A massive stark white beetle with silvery-black legs hungrily raises its dull silver mandibles. Equally spaced on the creature's head stare two sets of dull silvery-black eyes.","group":"Gelid Beetle","source":"Tome of Horrors Complete (3pp)","special_abilities":[{"type":"Cold","kind":"Ex","details":"A greater gelid beetle's body generates cold that deals an extra 1d8 points of cold damage every time it succeeds on a bite attack. Creatures attacking a greater gelid beetle unarmed or with natural weapons take this same cold damage each time one of their attacks hits."},{"type":"Cold Cloud","kind":"Ex","details":"Once per minute as a free action, a greater gelid beetle can emit a cloud of thick, billowing, icy cold vapors in a 20-foot radius around its body. The cloud is extremely thick and prevents effective ranged weapon attacks (except for magic rays). Melee attack and damage rolls suffer a -2 penalty in the cloud. Each round, on the beetle's turn, the cloud deals 2d6 points of cold damage to each creature within it. A successful DC 20 Fortitude save reduces the damage by half. The save DC is Constitution-based. The cloud lasts 1d4+3 rounds before dispersing."}],"description":"Greater gelid beetles are larger, meaner versions of the standard gelid beetle. They are almost always hungry and are usually encountered while hunting. These beetles enjoy the flesh of cold-dwelling animals such as moose, deer, snow leopards, and the like.\n\nGreater gelid beetles use their cold cloud when threatened or cornered.\n\nOnce the cloud has been released, the beetle either seeks escape (unless its hungry) or fights back with its powerful bite. Once its cold cloud recharges, the beetle releases it again if it's still in combat.","ecology":"","habitat_society":""}];
